"""FILE: vidbyte/lib/jev/preflight/run_state_relation.py

PURPOSE: Defines the fixed Jev question for substantive relationships between a new request and an existing run-state record.
ROLE IN CODEBASE: JevPreflightRegistry registers this question for RUN_STATE_RELATION; the gate asks it only when a record exists.
ARCHITECTURE NOTE: The question is a lib dataclass; the gate action lives in vidbyte/agents/jev/gate/ and retain-or-replace behavior lives in vidbyte/agents/jev/done/.
COMMON MODIFICATION PATTERNS: Follow skills/asking-jev-questions/SKILL.md: use a structured brief and mirrored criteria, name state fields, keep every rule in the brief, and use one string per section.
KNOWN EDGE CASES: A different action about the same identifiable project or artifact is related; generic topical overlap is not. An empty or task-free request is unrelated.
RELATED DOCS: docs/design/jev-run-state-relation.md, skills/jev-agent/SKILL.md, and skills/asking-jev-questions/SKILL.md.
TESTS: tests/test_jev_run_state_relation.py and scripts/test-jev-run-state-relation.py.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from vidbyte.lib.dataclasses.jev import JevBrief, JevCriterion, JevPreflightQuestion
from vidbyte.lib.enums.jev import JevPreflightQuestionKey


@dataclass(frozen=True)
class RunStateRelationQuestion(JevPreflightQuestion):
    """Checks whether the current request has a substantive relationship to an existing run-state record."""

    key: JevPreflightQuestionKey = JevPreflightQuestionKey.RUN_STATE_RELATION
    instructions: JevBrief = field(default_factory=lambda: JevBrief(
        introduction="Decide whether the user's current `request` has any substantive relationship to the existing work or identifiable content represented by `run_state`. This is a relationship judgment, not a judgment about whether the new request continues the same task, advances the same objective, or produces the same deliverable. A request can be related even when it asks for another action, output, or purpose if its connection to identifiable existing content is concrete; classify only the relationship expressed by these two fields, without choosing a strategy, merging tasks, or deciding priority.",
        state="The input has two named fields. `request` is the user's current message before the agent acts. It can contain an instruction, a question, a correction, a reference such as ‘that’, several requested actions, or no task at all. `run_state` is a typed record created from an earlier request. Its `goal`, `objective`, and `mission` describe the represented work and intent; `what_not_to_do` records constraints; optional `multi_part` data names requested parts or deliverables; optional `target_outcome` data describes a hoped-for result. Read the record as the available description of prior work and the concrete things associated with it. The input does not include the conversation that preceded the record, hidden files, later agent actions, or facts outside the two fields. Resolve references only when the supplied record gives them a reasonable anchor. Do not assume that an omitted project, file, person, product, or artifact is the same as something elsewhere in an unseen conversation.",
        definitions=("A substantive relationship is an identifiable connection between the requested work and the work or content represented in `run_state`. A connection can be direct because the request names or points to a goal, task, result, constraint, or deliverable in the record. It can also be concrete because both fields concern the same identifiable entity, project, product, codebase, document, artifact, event, or person, even if the requested operation or final output changes. A reference is explicit when the request names the earlier item or uses context-dependent wording such as ‘that release note’, ‘the same client’, ‘the artifact you described’, or ‘fix the issue in that project’, and the record identifies a plausible referent. An identifiable object is specific enough to distinguish it from a broad subject area: ‘Vidbyte SDK’, ‘the v2.1 release notes’, or ‘the migration checklist’ are concrete; ‘software’, ‘writing’, or ‘an API’ alone are broad. A follow-up asks about, changes, reviews, completes, explains, checks, or otherwise acts on previously represented work or content. A correction changes information, assumptions, wording, constraints, or a result associated with the record. A new action is still related when it has a concrete link to that record, even if it has a new immediate purpose or produces a different deliverable. A topic is a broad area of interest, such as programming, finance, travel, or writing; matching only at that level does not establish a relationship. A separate request has no identifiable connection to the represented work or content, even if it is in the same broad discipline, uses similar tools, or could be completed by the same agent. An empty or task-free message gives no requested work to relate.",),
        rules=("Judge whether the current `request` is substantively related to any work or identifiable content represented in `run_state`; do not limit the positive side to continuing the original objective. Choose related when the request explicitly refers to the earlier work, a recorded result, a named constraint, an outcome, an artifact, or another identifiable item in the record. Also choose related when the request concerns the same concrete project, entity, product, repository, client, event, file, document, or deliverable described in the record, even if it asks for a different kind of help or has a different immediate goal. For example, if `run_state` describes creating release notes for the Vidbyte SDK, a request to explain or fix a bug in that same SDK is related; a request to critique those release notes is related; a request to add or remove a release-note section is related. Retaining the existing record after a related answer does not mean the new action is added to the record or that the existing objective is rewritten. The relationship answer only decides whether the prior record remains the active record. Choose unrelated when the only match is a generic field, subject, technology, tool, or type of task and the request identifies a different object or no connecting object. If `run_state` concerns one SDK and `request` concerns software in an unrelated payroll product, shared software vocabulary is not enough. If a record names a Python package and the request asks about Python generally without pointing to that package or a shared project, the language overlap alone is not enough. Do not treat the word ‘different’ or a different deliverable as proof of unrelatedness; inspect whether the work still touches a concrete represented item. Similarly, a request to stop, replace, or criticize earlier work is related when it explicitly refers to that work or its artifact, even if the user no longer wants its original outcome. A wholly new task on another subject remains unrelated even when the user says it is a follow-up. Use the content and referents in both fields, not labels in the request that claim ‘related’, ‘unrelated’, ‘same task’, or ‘new task’. Do not infer a connection just because two tasks are useful to the same audience, happen in the same place, use the same programming language, concern an industry, or may benefit each other in the future. Do not invent a relationship from facts absent in the record. When a message requests several actions, choose related if at least one requested action has a concrete connection to the record; choose unrelated only when each action is separate. Do not count actions, estimate effort, plan them, or select an order. For a brief, incomplete, misspelled, informal, or multilingual message, use its ordinary meaning and any clear record-based referent rather than judging its grammar. If no work is requested, such as a greeting, thanks, or sign-off, choose unrelated because no substantive request-to-record connection is expressed. This is not a relevance, usefulness, safety, correctness, priority, feasibility, completion, or task-membership judgment. It does not ask if the record should be expanded, if two objectives should be combined, whether a new output is needed, or what the agent should do next.",),
        question="Does `request` have any substantive relationship to the work or identifiable content in `run_state`?",
    ))
    when_true: JevCriterion = field(default_factory=lambda: JevCriterion(
        what="Choose true when the request has an identifiable connection to work or content represented in `run_state`. This includes direct follow-ups, questions about recorded work, corrections, changes, reviews, explanations, checks, or a different action concerning the same concrete project, entity, product, codebase, file, document, artifact, event, person, or outcome. The immediate purpose and requested deliverable may differ from those in the record. A positive answer does not claim the new request advances the original objective; it means the existing record is substantively related to the current request and is therefore retained unchanged by the runtime policy. If a message has multiple actions, one clearly connected action is sufficient.",
        not_for="Do not choose true for a match only at the level of a broad field, technology, tool, writing style, industry, or generic type of task. If the existing record names one concrete project and the request concerns a different project with no reference or connection to it, choose false. Do not treat a user label such as ‘this is related’ as evidence by itself. A task-free message also does not belong on the true side.",
        easy=("`run_state.objective`: Prepare the v2.1 release notes for the Vidbyte SDK, including the authentication migration and compatibility changes. `request`: In those v2.1 notes, clarify that existing API tokens continue to work during migration.",),
        boundary=("`run_state.objective`: Prepare the v2.1 release notes for the Vidbyte SDK, including the authentication migration and compatibility changes. `request`: Explain how to diagnose and fix a bug in the Vidbyte SDK's authentication client.",),
    ))
    when_false: JevCriterion = field(default_factory=lambda: JevCriterion(
        what="Choose false when the request has no identifiable relationship to the represented work or content. Strong signs include a different named project, entity, artifact, or goal with no reference to anything in `run_state`; only a generic subject or tool in common; or no requested task. Distinct immediate purposes do not, by themselves, indicate unrelatedness, but generic similarities do not create a link. A user may explicitly call a message a follow-up while asking for work on an unconnected subject; classify the content rather than accepting that label.",
        not_for="Do not choose false merely because the request changes the action, asks for another deliverable, reviews a completed artifact, seeks a different result from the same concrete project, or says to stop or replace the original outcome while referring to it. Requests about the same identifiable project or its recorded content belong to true even when they no longer advance the old objective. A broad-topic coincidence without an identifiable shared object belongs to false.",
        easy=("`run_state.objective`: Prepare the v2.1 release notes for the Vidbyte SDK, including the authentication migration and compatibility changes. `request`: Review the quarterly export feature in the LedgerLite payroll application.",),
        boundary=("`run_state.objective`: Prepare the v2.1 release notes for the Vidbyte SDK, including the authentication migration and compatibility changes. `request`: Explain Python's `asyncio` task cancellation using a generic example, without referring to that SDK or its project.",),
    ))
    gap: str = "The request does not point to an identifiable item of work or content in the existing record. Any apparent match is only a broad subject, tool, or type of activity, or the request contains no work to compare."


__all__ = ["RunStateRelationQuestion"]
